void SdXMLDescriptionContext::endFastElement(sal_Int32 )
{
    if( msText.isEmpty() )
        return;

    try
    {
        uno::Reference< beans::XPropertySet > xPropSet(mxShape, uno::UNO_QUERY);
        if (!xPropSet)
            return;
        if( (mnElement & TOKEN_MASK) == XML_TITLE)
        {
            xPropSet->setPropertyValue(u"Title"_ustr, Any(msText));
        }
        else
        {
            xPropSet->setPropertyValue(u"Description"_ustr, Any(msText));
        }
    }
    catch( uno::Exception& )
    {
    }
}
// This method is called for all characters that are contained in the
// current element. The default is to ignore them.
void SdXMLDescriptionContext::characters( const OUString& rChars )
{
    msText += rChars;
}
